import re
import socket
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from http.client import HTTPException
from pathlib import Path

_PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
if str(_PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(_PROJECT_ROOT))

from src.pipeline.config import Paths, GraphLake

_HEADER_RE = re.compile(r"^# (\S+)  \((group\d+)\.dle\)$", re.MULTILINE)
_BODY_LIMIT = 4096
# Socket timeout on top of the server-side query timeout
_SOCKET_GRACE_S = 30


class _GraphLakeError(Exception):
    def __init__(self, kind: str, message: str, http_status: int | None = None):
        super().__init__(message)
        self.kind = kind
        self.message = message
        self.http_status = http_status

    def as_dict(self) -> dict:
        err = {"kind": self.kind, "message": self.message}
        if self.http_status is not None:
            err["http_status"] = self.http_status
        return err


def _timeout_seconds(value: str) -> float:
    m = re.fullmatch(r"(\d+(?:\.\d+)?)(ms|s|m|h)?", value.strip())
    if not m:
        return 60.0
    scale = {"ms": 0.001, "s": 1, "m": 60, "h": 3600}[m.group(2) or "s"]
    return float(m.group(1)) * scale


def _split_queries(path: Path) -> list[dict]:
    """Split a .rq file into one entry per `# <FlaggedClass>  (groupN.dle)` block."""
    text = path.read_text(encoding="utf-8")
    headers = list(_HEADER_RE.finditer(text))
    blocks = []
    for i, m in enumerate(headers):
        end = headers[i + 1].start() if i + 1 < len(headers) else len(text)
        blocks.append({
            "flagged_class": m.group(1),
            "group": m.group(2),
            "source_file": path.name,
            "sparql": text[m.start():end].strip() + "\n",
        })
    return blocks


def _request(method: str, url: str, *, headers: dict, data: bytes | None = None,
             timeout: float = 30) -> tuple[int, dict, bytes]:
    """Return (status, headers, body); non-2xx statuses are returned, not raised."""
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, dict(resp.headers), resp.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers or {}), e.read()


def _truncate(body: bytes) -> str:
    return body[:_BODY_LIMIT].decode("utf-8", errors="replace")


def _login(base_url: str) -> str:
    try:
        status, _, body = _request(
            "POST", f"{base_url}/admin/authenticate/password",
            headers={"Content-Type": "application/json"},
            data=json.dumps({"username": GraphLake.username, "password": GraphLake.password}).encode(),
        )
    except (urllib.error.URLError, socket.timeout, HTTPException, OSError) as e:
        raise _GraphLakeError("connection", f"login failed: {e}")
    if status != 200:
        raise _GraphLakeError("auth", f"login failed: {_truncate(body)}", status)
    try:
        return json.loads(body)["token"]
    except (ValueError, KeyError, TypeError):
        raise _GraphLakeError("invalid_response", f"login response has no token: {_truncate(body)}", status)


def _get_json_list(url: str, token: str) -> list:
    try:
        status, _, body = _request("GET", url, headers={"Authorization": f"Bearer {token}"})
    except (urllib.error.URLError, socket.timeout, HTTPException, OSError) as e:
        raise _GraphLakeError("connection", f"GET {url} failed: {e}")
    if status != 200:
        raise _GraphLakeError("http", f"GET {url}: {_truncate(body)}", status)
    try:
        data = json.loads(body)
    except ValueError:
        raise _GraphLakeError("invalid_response", f"GET {url}: {_truncate(body)}", status)
    if not isinstance(data, list):
        raise _GraphLakeError("invalid_response", f"GET {url}: expected a JSON array", status)
    return data


def _precheck(base_url: str, store: str, branch: str) -> str:
    """Log in and confirm store and branch exist; return the token."""
    token = _login(base_url)
    if store not in _get_json_list(f"{base_url}/stores", token):
        raise _GraphLakeError("not_found", f"store not found: {store}")
    quoted = urllib.parse.quote(store, safe="")
    branches = _get_json_list(f"{base_url}/stores/{quoted}/branches", token)
    names = [b.get("name") if isinstance(b, dict) else b for b in branches]
    if branch not in names:
        raise _GraphLakeError("not_found", f"branch not found: {store}/{branch}")
    return token


def _error_entry(kind: str, status: int | None, body: bytes | None, message: str | None = None) -> dict:
    """Build a query error from GraphLake's `{"error", "details"}` body, or the raw body."""
    details = None
    raw = None
    if body is not None:
        try:
            parsed = json.loads(body)
        except ValueError:
            parsed = None
        if isinstance(parsed, dict) and "error" in parsed:
            message = message or str(parsed["error"])
            details = parsed.get("details")
        else:
            raw = _truncate(body)
    return {
        "kind": kind,
        "message": message or (f"HTTP {status}" if status else "unknown error"),
        "details": details,
        "body": raw,
    }


def _run_query(base_url: str, store: str, branch: str, sparql: str, auth: dict) -> dict:
    """Run one query; return status, http_status, vars, bindings and error fields."""
    url = (
        f"{base_url}/stores/{urllib.parse.quote(store, safe='')}/query?"
        + urllib.parse.urlencode({"branch": branch, "timeout": GraphLake.query_timeout})
    )
    socket_timeout = _timeout_seconds(GraphLake.query_timeout) + _SOCKET_GRACE_S
    relogged = retried = False

    while True:
        headers = {
            "Content-Type": "application/sparql-query",
            "Accept": "application/sparql-results+json",
            "Authorization": f"Bearer {auth['token']}",
        }
        try:
            status, resp_headers, body = _request(
                "POST", url, headers=headers, data=sparql.encode("utf-8"), timeout=socket_timeout,
            )
        except socket.timeout as e:
            return {"status": "error", "http_status": None, "error": _error_entry("timeout", None, None, str(e) or "socket timeout")}
        except (urllib.error.URLError, HTTPException, OSError) as e:
            return {"status": "error", "http_status": None, "error": _error_entry("connection", None, None, str(e))}

        if status == 401 and not relogged:
            relogged = True
            try:
                auth["token"] = _login(base_url)
            except _GraphLakeError as e:
                return {"status": "error", "http_status": status, "error": _error_entry("auth", status, body, e.message)}
            continue
        if status == 429 and not retried:
            retried = True
            try:
                delay = float(resp_headers.get("Retry-After", "1"))
            except ValueError:
                delay = 1.0
            print(f"    rate limited, retrying in {delay:g}s ...", flush=True)
            time.sleep(delay)
            continue
        break

    if status != 200:
        kind = {401: "auth", 429: "rate_limited", 504: "timeout"}.get(status, "http")
        return {"status": "error", "http_status": status, "error": _error_entry(kind, status, body)}

    try:
        data = json.loads(body)
        return {
            "status": "ok",
            "http_status": status,
            "vars": data["head"]["vars"],
            "bindings": data["results"]["bindings"],
            "error": None,
        }
    except (ValueError, KeyError, TypeError) as e:
        return {"status": "error", "http_status": status,
                "error": _error_entry("invalid_response", status, None, f"invalid SPARQL JSON: {e}") | {"body": _truncate(body)}}


def run(
    source_dir: Path,
    output_dir: Path,
    *,
    force: bool = False,
    test_run: bool = False,
) -> bool:
    """Run every query in source_dir/queries*.rq; return False on any error."""
    output_dir.mkdir(parents=True, exist_ok=True)

    base_url = GraphLake.url.rstrip("/")
    store, branch = GraphLake.store, GraphLake.branch
    out_path = output_dir / f"{store}-{branch}.json"

    if out_path.exists() and not force:
        print(f"[run-flagged-queries] {out_path.name} already exists, skipping. Use --force to regenerate.")
        return True

    query_files = sorted(
        source_dir.glob("queries*.rq"),
        key=lambda p: int(re.search(r"(\d+)\.rq$", p.name).group(1)),
    )
    if not query_files:
        print(f"[run-flagged-queries] No queries*.rq files found in {source_dir.relative_to(_PROJECT_ROOT)}.")
        return True

    result = {
        "store": store,
        "branch": branch,
        "graphlake_url": base_url,
        "run_at": datetime.now(timezone.utc).isoformat(),
        "test_run": test_run,
        "error": None,
        "summary": {"queries": 0, "ok": 0, "error": 0, "rows": 0},
        "queries": [],
    }

    try:
        auth = {"token": _precheck(base_url, store, branch)}
    except _GraphLakeError as e:
        result["error"] = e.as_dict()
        out_path.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        print(f"[run-flagged-queries] Pre-check failed: {e.message}", flush=True)
        print(f"  Written: {out_path.relative_to(_PROJECT_ROOT)}")
        return False

    print(f"[run-flagged-queries] {store}/{branch} at {base_url} ...", flush=True)

    summary = result["summary"]
    for query_file in query_files:
        for block in _split_queries(query_file):
            start = time.monotonic()
            outcome = _run_query(base_url, store, branch, block["sparql"], auth)
            duration_ms = round((time.monotonic() - start) * 1000)

            bindings = outcome.get("bindings", [])
            rows = [{var: b["value"] for var, b in binding.items()} for binding in bindings]
            result["queries"].append({
                **block,
                "status": outcome["status"],
                "http_status": outcome["http_status"],
                "duration_ms": duration_ms,
                "row_count": len(rows),
                "vars": outcome.get("vars", []),
                "rows": rows,
                "raw": bindings,
                "error": outcome["error"],
            })

            summary["queries"] += 1
            if outcome["status"] == "ok":
                summary["ok"] += 1
                summary["rows"] += len(rows)
                print(f"  {block['flagged_class']}: ok, {len(rows)} row(s)", flush=True)
            else:
                summary["error"] += 1
                err = outcome["error"]
                print(f"  {block['flagged_class']}: error ({err['kind']}): {err['message']}", flush=True)

            if test_run:
                print("  --test-run: stopping after first query.")
                break
        if test_run:
            break

    out_path.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(
        f"[run-flagged-queries] {summary['queries']} queries: {summary['ok']} ok, "
        f"{summary['error']} error, {summary['rows']} rows",
        flush=True,
    )
    print(f"  Written: {out_path.relative_to(_PROJECT_ROOT)}")
    return summary["error"] == 0


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Run flagged SPARQL queries against GraphLake and record results."
    )
    parser.add_argument("--force", action="store_true", help="Overwrite the existing output file.")
    parser.add_argument("--test-run", action="store_true", help="Run only the first query and stop.")
    args = parser.parse_args()

    ok = run(Paths.flagged_queries_sparql, Paths.flagged_results, force=args.force, test_run=args.test_run)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
